Method.Implementation:
    set ^webService("WorkFlowEntries Start") = $ZDATETIME($HOROLOG,3, 1) _", Array count: " _ searchArr.Count() 
    set count = 250,   statusType = "", transType = "", errorType = "", dateRange ="", userNm ="", id = ""
    set senderID = "", receiverID = ""
    for ind=1:1:searchArr.Count()
    {
	   set param = searchArr.GetAt(ind)
	   set val = $ZSTRIP($PIECE(param, "::", 2), "<>W")
	   // set ^webService("WorkFlowEntries - " _ param) = val
	   if ( param [ "StatusTypes")
	   {
		   set statusType = val
	   } 
	   elseif ( param [ "TransactionType")
	   {
		   set transType = val
		   if (transType [ "837")
		   {
			   set transType = "%837%"
		   }
	   }
	   elseif ( param [ "ErrorType")
	   {
		   set errorType = val
	   }
	   elseif ( param [ "DateRange")
	   {
		   set dateRange = val
	   }
	   elseif ( param [ "Count")
	   {
		   set count = val
	   }
	   elseif ( param [ "CurrentUser")
	   {
		   set userNm = val
	   }
	   elseif ( param [ "receiverID")
	   {
		   set receiverID = val
	   }
	   elseif ( param [ "senderID")
	   {
		   set senderID = val
	   }

	   elseif ( param [ "ID")
	   {
		   set id = val
	   }
	   elseif ( param [ "AssignedUser")
	   {
		   set assignedUser = val
	   }

    }

    Set tArr = []
    #dim rs As %SQL.StatementResult
    set dtStr = "", sqlStr = ""

    Do $SYSTEM.SQL.Util.SetOption("SelectMode",2)

    if (id '= "")
    {
	    set sqlStr = "SELECT top " _ count _" * FROM IHC_ITF_ITFCOMMON_X12.WorkFlow where ID = " _ id
    }
    else
    {


	    set errStr = ""
	    set transactionStr = ""
	    set statStr = ""

	    if (errorType '= "All")
	    {
		    set errStr = " AND ErrorType = '" _ errorType _"'"
	    }
	    if (transType '= "All")
	    {
	       set transactionStr = " AND TransactionType like '"_ transType _"'"
	    }
	    if (dateRange '= "")
	    {
		    set dtStr = " AND CreateDtTm " _ dateRange
	    }

	    if (senderID '= "")
	    {
		    if (senderID [ "%")
	    	{
		    	set transactionStr = transactionStr _ " AND InterchangeSenderID like '" _ senderID _"'"
	    	}
	    	else
	    	{
		    	set transactionStr = transactionStr _ " AND InterchangeSenderID = '" _ senderID _"'"
	    	}
	    }
	    if (receiverID '= "")
	    {
		    if (receiverID [ "%")
	    	{
		    	set transactionStr = transactionStr _ " AND InterchangeReceiverID like '" _ receiverID _"'"
	    	}
	    	else
	    	{
		    	set transactionStr = transactionStr _ " AND InterchangeReceiverID = '" _ receiverID _"'"
	    	}

	    }

	    set statStr1 = "", statStr2 = ""
	    for ind=1:1:$L(statusType, ";")
	    {

	      set stat = $PIECE(statusType, ";", ind) 

		    if (stat = "Assigned To Me")
		    {	    
		       set statStr1 =  " (WorkStatus ='Assigned' AND AssignedUser = '" _userNm _ "')"
	        }
	        elseif ((stat = "Assigned To Others") && (assignedUser '= ""))
		    {

		       set statStr2 =  " (WorkStatus ='Assigned' AND AssignedUser = '" _ assignedUser _ "')"
	        }
	        elseif (stat = "Assigned To Others") 
		    {

		       set statStr2 =  " (WorkStatus ='Assigned' AND AssignedUser != '" _ userNm _ "')"
	        }
	        else
	        {
		        if (statStr = "")
		        {
		        	set statStr =  " WorkStatus IN ('" _ stat _"'"
		        }
		        else
		        {
			        set statStr = statStr _ ", '" _ stat _"'"
		        }
	        }
	    }
	    if (statStr '= "")
	    {
		    set statStr = statStr _ ")"
	    }
	    if (statStr1 '= "")
	    {
		    if (statStr = "")
	    	{
		    	set statStr = statStr1
	    	}
		    else
		    {
		    	set statStr = statStr _ " OR " _ statStr1
		    }
	    }
	    if (statStr2 '= "")
	    {
		    if (statStr = "")
	    	{
		    	set statStr = statStr2
	    	}
		    else
		    {
		    	set statStr = statStr _ " OR " _ statStr2
		    }
	    }
	    if (statStr '= "")
	    {
		    set statStr = "(" _ statStr _ ")"
	    }


        set sqlStr = "SELECT top " _ count _" * FROM IHC_ITF_ITFCOMMON_X12.WorkFlow where " _ statStr _ errStr _ transactionStr _ dtStr _ "  order by CreateDtTm desc"
	}

    set ^webService("WorkFlowEntries SQL") = sqlStr
	Set rs = ##class(%SQL.Statement).%ExecDirect(,sqlStr)

    set ^webService("WorkFlowEntries rs") = "rs " _ $ZDATETIME($HOROLOG,3, 1)
	While rs.%Next() {

			set ^webService("WorkFlowEntries x12Data") = rs.%Get("ID") _ $ZDATETIME($HOROLOG,3, 1)
			Do tArr.%Push({
				"Operation":"WorkFlowEntries",
				"ID": (rs.%Get("ID")),
				"InterchangeReceiverID": (rs.%Get("InterchangeReceiverID")),
				"InterchangeSenderID": (rs.%Get("InterchangeSenderID")),
				"Resent": (rs.%Get("Resent")),
				"TransactionType": (rs.%Get("TransactionType")),
				"CreateDtTm": (rs.%Get("CreateDtTm")),
				"ResolveDtTm": (rs.%Get("ResolveDtTm")),
				"WorkStatus": (rs.%Get("WorkStatus")),
				"AssignedUser": (rs.%Get("AssignedUser")),
				"ErrorType": (rs.%Get("ErrorType")),
				"Error": (rs.%Get("Error")),
				"LastmodDtTM": (rs.%Get("LastmodDtTM")),
				"LastmodID": (rs.%Get("LastmodID"))	,
				"SessionID": (rs.%Get("SessionID"))	
			})

	}
    set ^webService("WorkFlowEntries") = "End: " _ $ZDATETIME($HOROLOG,3, 1)
	Do ..%SetStatusCode(200)

	return tArr

	Set tArr = []
	#dim xObj As IHC.X12.SharedData = $$$NULLOREF
    set x12Str = "", fileName = ""
    set ^webService("WorkFlowEntry for" _ ID) = SessionID _ "@ " _ $ZDATETIME($HOROLOG,3, 1)
    if (SessionID '= "")
    {
	    set sId = SessionID
	    &SQL(SELECT ID into :ID from IHC_ITF_ITFCOMMON_X12.WorkFlow where SessionID = :sId)
	    set ^webService("WorkFlowEntry ID from SessionID ") = sId _"= " _ ID
    }
    if (ID '= "")
    {
		set ^webService("WorkFlowEntry Start") = ID	
		set ^webService("WorkFlowEntry ID") = ID  _ "@ " _ $ZDATETIME($HOROLOG,3, 1)

		set obj = ##class(IHC.ITF.ITFCOMMON.X12.WorkFlow).%OpenId(ID,,.sc)
		set ^webService("WorkFlowEntry open: ") = sc _", Find ID " _ obj.OrigX12Id _ " from "_ obj.TransactionType
	}
	if (obj.SessionID > 0)
	{
		set classname = "IHC.X12.Data" _ obj.TransactionType
		if (obj.TransactionType [ "837")
		{
			set classname = "IHC.X12.Data837" //Remove I, P, D
		}
		set sqlStr = "select * from " _ classname _ " where SessionID = " _ obj.SessionID
		set ^webService("WorkFlowEntry SQL") = sqlStr
		Set rs = ##class(%SQL.Statement).%ExecDirect(,sqlStr)

	    set ^webService("WorkFlowEntry rs") = "rs " _ $ZDATETIME($HOROLOG,3, 1)
		While rs.%Next() {
			set x12Str = rs.%Get("x12Data")
		}

		if (x12Str = "")
		{
			#dim x12Doc As EnsLib.EDI.X12.Document = ##class(EnsLib.EDI.X12.Document).%OpenId(obj.OrigX12Id,,.sc)

			set ^webService("WorkFlowEntry open2: ") = sc _", " _ x12Doc
			if ($IsObject(x12Doc))
			{
				set x12Str = x12Doc.OutputToString()
				set fileName = "X12.Document ID: " _ x12Doc.%Id()
			}
		}
		if (x12Str = "")
		{
			set x12Str = "SQL: " _ sqlStr _ " failed"
		}
	}
	elseif (obj.OrigX12Id > 0)
	{
		set classname = "IHC.X12.Data" _ obj.TransactionType
		if (obj.TransactionType [ "837")
		{
			set classname = "IHC.X12.Data837" //Remove I, P, D
		}

		  $$$TRACE( "Check class: " _ classname _ " for Id: " _ obj.OrigX12Id)

		 if ( $classmethod(classname,"%ExistsId",obj.OrigX12Id) )
		 {
			 set xObj = $classmethod(classname,"%OpenId",obj.OrigX12Id)
			 if ($ISOBJECT(xObj))
			 {
				set x12Str = xObj.x12Data
				set fileName = xObj.FileName
				set ^webService("WorkFlowEntry Class") = classname _", file: " _ xObj.FileName
			}
		}

		if (x12Str = "")
		{
			#dim x12Doc As EnsLib.EDI.X12.Document = ##class(EnsLib.EDI.X12.Document).%OpenId(obj.OrigX12Id,,.sc)

			set ^webService("WorkFlowEntry open2: ") = sc _", " _ x12Doc
			if ($IsObject(x12Doc))
			{
				set x12Str = x12Doc.OutputToString()
				set fileName = "X12.Document ID: " _ x12Doc.%Id()
			}
		}
		if (x12Str = "")
		{
			set x12Str = x12Doc.OutputToString()
			set fileName = "X12.Document ID: " _ x12Doc.%Id()
		}
	}
	else
	{
		set x12Str = "X12 not found"
	}
	set ^webService("WorkFlowEntry x12: ") = fileName _", X12 length: " _ $L(x12Str)
	set errStr = (obj.ErrorType) _" error: " _ (obj.Error)
	Do tArr.%Push({
		"Operation":"WorkFlowEntry",
				"ID": (ID),
				"Filename": (fileName),
				"OrigX12Id": (obj.OrigX12Id),
				"Error": (errStr),
				"X12": (x12Str),
				"InterchangeSenderID": (obj.InterchangeSenderID),
				"InterchangeReceiverID": (obj.InterchangeReceiverID),
				"Status":(obj.WorkStatus),
				"AssignedUser": (obj.AssignedUser)

	})	   
	if ($IsObject(obj.ErrList))
	{
		set ^webService("WorkFlowEntry ErrList: ") = obj.ErrList.Count()
		  for i=1:1:obj.ErrList.Count()
		  {
				Do tArr.%Push({	
				"stNum": (obj.ErrList.GetAt(i).stNum),		
				"segNum": (obj.ErrList.GetAt(i).segNum),
				 "segErrCode": (obj.ErrList.GetAt(i).segErrCode),
				 "segErrStr": (obj.ErrList.GetAt(i).segErrStr ),
				 "eleNum": (obj.ErrList.GetAt(i).eleNum ),
				 "eleErrCode": (obj.ErrList.GetAt(i).eleErrCode ),
				 "eleErrStr": (obj.ErrList.GetAt(i).eleErrStr), 
				 "x12Data": (obj.ErrList.GetAt(i).x12Data )
				})
				set ^webService("WorkFlowEntry ErrList ") = i _ ". Seg Num: " _ obj.ErrList.GetAt(i).segNum



		  }
	}


	if ( ($IsObject(obj.FlowList)) && (obj.FlowList.Count() > 0 ) )
	{
		set ^webService("WorkFlowEntry FlowList: ") = obj.FlowList.Count()
		  for i=1:1:obj.FlowList.Count()
		  {
				Do tArr.%Push({	
				"lnNum": (i),
				"Status": (obj.FlowList.GetAt(i).Status),
				 "ModUser": (obj.FlowList.GetAt(i).ModUser),
				 "ModDateTime": (obj.FlowList.GetAt(i).ModDateTime ),
				 "Notes": (obj.FlowList.GetAt(i).Notes )
				})
				set ^webService("WorkFlowEntry History ") = i _ ". Status: " _ obj.FlowList.GetAt(i).Status

		  }
	}
	else
	{
		Do tArr.%Push({	
				"lnNum": (i),
				"Status": "New",
				 "ModUser": "System",
				 "ModDateTime": (obj.CreateDtTm ),
				 "Notes": ""
				})
	}
	Do ..%SetStatusCode(200)

	return tArr

    Set tArr = []
    set stat = $$$OK, ID = "", status = "", assignedUser = "", userNm = "", notes =""
    for ind=1:1:searchArr.Count()
    {
	   set param = searchArr.GetAt(ind)
	   set val = $ZSTRIP($PIECE(param, "::", 2), "<>W")
	   set ^webService("UpdateWorkFlowEntry - " _ param) = val
	   if ( param [ "ID")
	   {
		   set ID = val
	   } 
	   elseif ( param [ "Status")
	   {
		   set status = val
	   } 
	   elseif ( param [ "AssignedUser")
	   {
		   set assignedUser = val
	   }
	   elseif ( param [ "User")
	   {
		   set userNm = val
	   } 
	   elseif ( param [ "Notes")
	   {
		   set notes = val
	   } 
    }
    if (assignedUser = "")
    {
	    set assignedUser = userNm
    }

	set wfObj = ##class(IHC.ITF.ITFCOMMON.X12.WorkFlow).%OpenId(ID)
	if ($IsObject(wfObj))
	{
		set dtTm = $ZDATETIME($HOROLOG,3, 1)
		if (status [ "Resolve")
		{ 
		  set wfObj.WorkStatus = "Resolved"
		  set wfObj.ResolveDtTm = dtTm
		}
		if (status = "Assigned")
		{ 
		 set wfObj.AssignedUser = assignedUser 
		}
		set wfObj.LastmodDtTM =	 dtTm 

		set hist = ##class(IHC.ITF.ITFCOMMON.X12.WorkHistory).%New()
		set hist.Status= status
		set wfObj.WorkStatus = status
		set hist.ModUser= userNm 
		set wfObj.LastmodID = userNm
		set hist.ModDateTime = dtTm
		set hist.Notes= notes

		Do wfObj.FlowList.Insert(hist)


		set stat = wfObj.%Save()
		set ^webService("WorkFlowEntry Save ") = stat

    	if (status [ "Resend")
		{
		    set source = ##class(EnsLib.EDI.X12.Document).ImportFromString(data)
	 		if ( ($ISOBJECT(source)) && (source.%Extends("EnsLib.EDI.X12.Document")) )
	 		{
			    set rsndDirc = "/itf-share/itf-tmp/" _ $NAMESPACE _ "/RESEND/"
			    if (source.DocType = "")
			    {
			    	set source.DocType="HIPAA_5010:Interchange:Group"
			    }
			    if ('##class(%File).DirectoryExists(rsndDirc))
			    {
				    Do ##class(%File).CreateDirectoryChain(rsndDirc)
			    }
			    set ctrlNum = $ZSTRIP(source.GetValueAt("ISA:InterchangeControlNumber"), "<>WC")
			    set ^webService("UpdateWorkFlowEntry File SQLCODE") = SQLCODE _", data: " _ $L(data) _ ", ctrl: " _ ctrlNum
			    set ^webService("UpdateWorkFlowEntry Direc") = ##class(%File).DirectoryExists(rsndDirc)
			    set flNm = $REPLACE(rsndDirc _ type_"-"_  recv _"-"_	send_"-"  _ ctrlNum_"-"_ usr_"-"_$ZDATETIME($HOROLOG,3, 1) _ "-Resend.dat", " ","")
			    set fl = ##class(%File).%New(flNm)
			    set stat = fl.Open("WN")
			    if (stat)
			    {
				    set ^webService("UpdateWorkFlowEntry Resend file") = flNm _ ": " _ stat
				    Do fl.Write(data)
				    Do fl.Close()

				    &SQL(UPDATE IHC_ITF_ITFCOMMON_X12.WorkFlow set ResendFile = :flNm, Resent = 1 where ID = :ID)

				    set ^webService("UpdateWorkFlowEntry Resend file") = flNm _", " _ SQLCODE
			    }
			    else
			    {
				    set ^webService("UpdateWorkFlowEntry Error") = " Cound not create file: " _ flNm _", status: " _ stat
			    }
	 		}
	    }

	}
	else
	{
		    set ^webService("UpdateWorkFlowEntry OpenId failed: ") = ID
		    set stat = $$$ERROR("Object not found: " _ ID)
	}

	Do tArr.%Push({		
		"ID": (ID),
		"Status": (stat)
	})
	Do ..%SetStatusCode(200)

	return tArr

Set tArr = [] set ^webService("GetIrisUsers") = "Start: " _ $ZDATETIME($HOROLOG,3, 1) Set rs = ##class(%SQL.Statement).%ExecDirect(,"SELECT * from IHC_ITF_ITFCOMMON_X12.IrisUsers")
set ^webService("GetIrisUsers rs") = "rs " _ $ZDATETIME($HOROLOG,3, 1)
While rs.%Next() {
Do tArr.%Push({ "Operation": "GetUsers", "ID": (rs.%Get("ID")), "UserName": (rs.%Get("UserName")), "FullName": (rs.%Get("FullName")), "GrantedRoles": (rs.%Get("GrantedRoles"))}) }
set ^webService("GetIrisUsers") = "Return: " _ tArr.%Size() _" @ " _ $ZDATETIME($HOROLOG,3, 1) Do ..%SetStatusCode(200)
return tArr

    //(Place business logic here)
    //Do ..%SetStatusCode(<HTTP_status_code>)
    //Do ..%SetHeader(<name>,<value>)
    //Quit (Place response here) ; response may be a string, stream or dynamic object
    set ^webService("RdpCrystalEntries") = ID _", " _ SessionID _" @ " _ $ZDATETIME($HOROLOG,3, 1)
    set sqlStr = "", x12Id = "", wfStatus = "Data Error"
    #dim tArr As %Library.DynamicArray = []
    #dim rdpIds As %ListOfDataTypes = ##class(%ListOfDataTypes).%New()

    if (TransactionType [ "837")
    {

	    set TransactionType = "837"
    }

    if (ID '= "")
    {
	    DO rdpIds.Insert(ID)
    	Do ..GetRows(rdpIds, tArr)
    	return tArr
    }

    elseif((X12DataId '= "") && (TransactionType '= ""))
    {
	    set ^webService("RdpCrystalEntries from X12DataId ") = "X12DataId = " _ X12DataId
	     set sqlStr = "SELECT ID, X12DataId FROM IHC_ITF_ITFCOMMON_X12.RdpValidationErrors " _
			"where X12DataId = " _ X12DataId
    }
    elseif((SessionID '= "") && (TransactionType '= ""))
    {
	    set ^webService("RdpCrystalEntries from SessionID ") = "SessionID = " _ SessionID
	    set sqlStr = "SELECT r.ID, x.ID FROM IHC_ITF_ITFCOMMON_X12.RdpValidationErrors r, IHC_X12.Data" _ TransactionType _ " x " _
			"where r.SessionId = " _ SessionID _"  and r.SessionId = x.SessionId and x12DataParentId is null "
    }
    elseif((WFID '= "") && (TransactionType '= ""))
    {
	    set ^webService("RdpCrystalEntries from WFID ") = "WFID = " _ WFID
	    set sqlStr = "SELECT distinct r.ID, x.ID FROM IHC_ITF_ITFCOMMON_X12.RdpValidationErrors r, IHC_X12.Data" _ TransactionType _ " x where r.SessionId = " _
			"(select SessionID from IHC_ITF_ITFCOMMON_X12.WorkFlow where Id = " _ WFID _" ) and r.SessionID = x.SessionID and x12DataParentId is null"
    }
    else
    {
	    Do ..%SetStatusCode(200)
    	Quit "Required parameters are not sent to create SQL"
    }
    set ^webService("RdpCrystalEntries SQL") = sqlStr
    #dim rset AS %SQL.StatementResult = ##class(%SQL.Statement).%ExecDirect(,sqlStr)

    if rset.%SQLCODE=0 
    { 
      while (rset.%Next())      
     	{ 
     		Do rdpIds.Insert(rset.%GetData(1)) 
     		set x12Id = rset.%GetData(2)   		
     	}

    }
    else { 
    	set ^webService("RdpCrystalEntries SQLCODE") = "ExecDirect SQLCODE="_rset.%SQLCODE_", " _ rset.%Message  
    }
    if (x12Id = "")
    {
	    // TP error, not Data (will be in WorkFlow)
	    if ((WFID '= "") && (TransactionType '= ""))
    	{
	    	set ^webService("RdpCrystalEntries: X12 from WorkFlow WFID ") = "WFID = " _ WFID

	    	set sqlStr = "SELECT x.ID, w.Error FROM IHC_X12.Data" _ TransactionType _ 
	    	    " x, IHC_ITF_ITFCOMMON_X12.WorkFlow w where w.ID = " _ WFID _
			    " AND w.SessionId = x.SessionId  and x12DataParentId is null"
			set rset = ##class(%SQL.Statement).%ExecDirect(,sqlStr)
		    if rset.%SQLCODE=0 
		    { 
		      if (rset.%Next())      
		     	{ 
		     		set x12Id = rset.%GetData(1) 
		     		set wfStatus = rset.%GetData(2)
		     	}

		    }
    	}
    	elseif ((SessionID '= "") && (TransactionType '= ""))
    	{
	    	set ^webService("RdpCrystalEntries: X12 from WorkFlow WFID ") = "SessionID = " _ SessionID

	    	set sqlStr = "SELECT x.ID, w.Error FROM IHC_X12.Data" _ TransactionType _ 
	    	    " x, IHC_ITF_ITFCOMMON_X12.WorkFlow w where w.SessionID = " _ SessionID _
			    " AND w.SessionId = x.SessionId  and x12DataParentId is null"
			set rset = ##class(%SQL.Statement).%ExecDirect(,sqlStr)
		    if rset.%SQLCODE=0 
		    { 
		      if (rset.%Next())      
		     	{ 
		     		set x12Id = rset.%GetData(1) 
		     		set wfStatus = rset.%GetData(2)
		     	}

		    }
    	}
    }
	if (x12Id '= "")
    {    

		set classname = "IHC.X12.Data" _ TransactionType
		if (TransactionType [ "837")
		{
			set classname = "IHC.X12.Data837" //Remove I, P, D
		}

		  set ^webService("RdpCrystalEntries Check class: ") = classname _ " for Id: " _ x12Id

		 if ( $classmethod(classname,"%ExistsId",x12Id) )
		 {
			 #dim xObj As IHC.X12.SharedData = $classmethod(classname,"%OpenId",x12Id)
			 if ($ISOBJECT(xObj))
			 {
				 if ($L(xObj.x12Data) > 0)
				 {
					set x12Str = xObj.x12Data
				 }
				 elseif (xObj.x12DataStream.Size > 0)
				 {

						 #dim len As %Integer = 3641000
						 set x12Str =  xObj.x12DataStream.Read(.len,.sc) 
						 If $$$ISERR(sc) 
						 {
							 set x12Str = "ERROR: " _ sc  
						 }
						 If 'xObj.x12DataStream.AtEnd {
							 set x12Str =  x12Str _ "....(" _ $L(x12Str) _ " of " _ xObj.x12DataStream.Size _")"
						 } 

				 }
				 else
				 {
					 set x12Str = "X12 not found in " _ classname
				 }
				set fileName = xObj.FileName
				set ^webService("RdpCrystalEntries Class") = classname _", file: " _ xObj.FileName
			}
		}

		if (x12Str = "")
		{
			#dim x12Doc As EnsLib.EDI.X12.Document = ##class(EnsLib.EDI.X12.Document).%OpenId(x12Id,,.sc)

			set ^webService("RdpCrystalEntries open2: ") = sc _", " _ x12Doc

			set x12Str = x12Doc.OutputToString()

			set fileName = "X12.Document ID: " _ x12Doc.%Id()

		}
		if (x12Str = "")
		{
			set x12Str = x12Doc.OutputToString()
			set fileName = "X12.Document ID: " _ x12Doc.%Id()
		}

		set ^webService("RdpCrystalEntries x12: ") = x12Id _": " _ fileName _", X12 length: " _ $L(x12Str)

		Do tArr.%Push({
			"Operation":"RdpCrystalEntries",
					"Filename": (fileName),
					"OrigX12Id": (x12Id),
					"X12": (x12Str),
					"Error": (wfStatus)

		})
		set ^webService("RdpCrystalEntries RDP ids ") = rdpIds.Count()

		if (rdpIds.Count() > 0)
		{

        	Do ..GetRows(rdpIds, tArr)
		}

        Do ..%SetStatusCode(200)
        return tArr
	} 
	else {

	    Do ..%SetStatusCode(200)
	    Do tArr.%Push({
			"Operation":"RdpCrystalEntries",
