    set tableName = "IHC_ITF_ITFCOMMON_X12.RdpValidationErrors"

    set propertyList = ##class(%Library.ListOfDataTypes).%New()

	Do ..getColumnNames(tableName, propertyList)
	#dim rs As %SQL.StatementResult

	Do $SYSTEM.SQL.Util.SetOption("SelectMode",2)

	for ind=1:1:ids.Count()
	{

		    set sqlStr = "SELECT * FROM "_ tableName _ "  WHERE ID = '" _ ids.GetAt(ind) _"'"
		    if (sqlStr '= "")
		    {
			    Set rs = ##class(%SQL.Statement).%ExecDirect(,sqlStr )
			    set ^webService(tableName _" ExecDirect: ") = rs.%SQLCODE
				Do ..populateArray(tableName, rs , tArr, propertyList)
		    }
	}

	set ^webService(tableName _ " End") = sqlStr _ " - End, count: " _ rs.%ROWCOUNT _ " @ " _ $ZDATETIME($HOROLOG,3, 1)
	Do ..%SetStatusCode(200)

	return tArr

// All Column names


	Set prop=""
	Do propertyList.Insert("ID")
	set clsNm = $REPLACE(tableName,"_",".")
	For {
		Set prop=$$$comMemberNext(clsNm,$$$cCLASSproperty,prop) Quit:prop=""
		If (' ((prop [ "OID") || (prop [ "%") ) )
		{							
			Do propertyList.Insert(prop) 
		}
	}


	While rs.%Next() {

    	if ( rs.%SQLCODE = 0)
    	{

    		set ^webService(tableName _ " rs: ") = rs.%SQLCODE _ " at " _ $ZDATETIME($HOROLOG,3, 1) _ ", ID: " _ (rs.%Get("ID"))
    		set innerArr = []
    		set val = ""
    		set dataType = propertyList.Count()

    		for ind=1:1:propertyList.Count()
    		{
    		    set column = propertyList.GetAt(ind)


    		    set val = rs.%Get(column)

    			if (ind=1)
    			{
    				set innerArr={}.%Set(column,(val))
    			}
    			else
    			{
	    			Do innerArr.%Set(column,(val))
    			}

    		}

    		Do tArr.%Push((innerArr))
    	}


	}
	set ^webService(tableName _ " array size: ") = tArr.%Size()
